from itertools import combinations
from collections import defaultdict, Counter
import json, hashlib

# Partitions are weakly decreasing tuples of positive parts. This routine is used
# only to index bases; Pieri and LR products below are separate implementations.
def parts_box(r,q,maxpart=None,maxlen=None):
    if maxpart is None: maxpart=q
    if maxlen is None: maxlen=r
    out=[]
    def rec(pref,last,left):
        out.append(tuple(pref))
        if left==0: return
        for x in range(min(last,q),0,-1):
            rec(pref+[x],x,left-1)
    rec([],maxpart,maxlen)
    return out

def size(p): return sum(p)
def contains(nu,mu):
    return all((nu[t] if t<len(nu) else 0)>=(mu[t] if t<len(mu) else 0) for t in range(len(mu)))
def cells(p): return {(a+1,b+1) for a,x in enumerate(p) for b in range(x)}
def fmt(p): return '0' if not p else ''.join(map(str,p))

r,q,i,j=3,6,2,2
B=parts_box(r,q)
J=[p for p in B if contains(p,(2,2))]
J.sort(key=lambda p:(size(p),p))
cols={p:t for t,p in enumerate(J)}
free=[(2,2),(3,2),(3,3)]
assert all(x in cols for x in free)
free_idx={cols[x] for x in free}

# Independent Pieri product: enumerate containing partitions and test directly
# that the skew difference has k cells in pairwise distinct columns.
def pieri(mu,k):
    cm=cells(mu)
    ans={}
    for nu in B:
        if not contains(nu,mu) or size(nu)-size(mu)!=k: continue
        diff=cells(nu)-cm
        if len(diff)==k and len({b for a,b in diff})==k:
            ans[nu]=1
    return ans

pieri_rows=[]
for mu in J:
    for k in range(1,q+1):
        d=pieri(mu,k)
        if d:
            pieri_rows.append((size(mu)+k, 'h%d*%s'%(k,fmt(mu)), {cols[x]:v for x,v in d.items()}))

# Completely separate LR implementation: enumerate semistandard skew tableaux
# in reading order (top rows first, each right-to-left), imposing lattice-word
# inequalities after each letter. This never calls pieri().
def lr_coeff(alpha,mu,nu):
    if not contains(nu,mu) or size(alpha)+size(mu)!=size(nu): return 0
    sh=[]
    for rr in range(1,len(nu)+1):
        lo=(mu[rr-1] if rr<=len(mu) else 0)+1
        for cc in range(nu[rr-1],lo-1,-1): # right-to-left
            sh.append((rr,cc))
    target=[0]+list(alpha)
    maxv=len(alpha)
    filled={}; cnt=[0]*(maxv+1); total=0
    def go(t):
        nonlocal total
        if t==len(sh):
            if cnt[1:]==target[1:]: total+=1
            return
        rr,cc=sh[t]
        right=filled.get((rr,cc+1))
        above=filled.get((rr-1,cc))
        for x in range(1,maxv+1):
            if cnt[x]>=target[x]: continue
            # row weak increase left-to-right; column strict increase top-to-bottom
            if right is not None and x>right: continue
            if above is not None and above>=x: continue
            if x>1 and cnt[x]+1>cnt[x-1]: continue
            filled[(rr,cc)]=x; cnt[x]+=1
            go(t+1)
            cnt[x]-=1; del filled[(rr,cc)]
    go(0)
    return total

# All positive Schur multipliers in the finite box are used for the direct LR presentation.
lr_rows=[]
for alpha in B:
    if not alpha: continue
    for mu in J:
        d={}
        targetdeg=size(alpha)+size(mu)
        for nu in J:
            if size(nu)!=targetdeg: continue
            z=lr_coeff(alpha,mu,nu)
            if z: d[cols[nu]]=z
        if d:
            lr_rows.append((targetdeg, '%s*%s'%(fmt(alpha),fmt(mu)), d))

# For each degree, choose a square unit-pivot Pieri block on all non-free columns.
# Exact Gauss-Jordan uses only integral operations with unit pivots. It also returns
# the reduced selected relations e_c + sum_f a_cf e_f = 0.
def select_block(d):
    C=[x for x,p in enumerate(J) if size(p)==d and x not in free_idx]
    R=[row for row in pieri_rows if row[0]==d]
    # augmented rows: C coordinates and coefficient combination in original R
    work=[]
    for ri,row in enumerate(R):
        work.append([[row[2].get(c,0) for c in C], [1 if z==ri else 0 for z in range(len(R))]])
    piv=[]
    for k in range(len(C)):
        found=None
        for u in range(k,len(work)):
            for v in range(k,len(C)):
                if abs(work[u][0][v])==1:
                    found=(u,v); break
            if found: break
        if found is None: raise RuntimeError('no unit pivot degree %d stage %d'%(d,k))
        u,v=found; work[k],work[u]=work[u],work[k]
        for row in work: row[0][k],row[0][v]=row[0][v],row[0][k]
        if work[k][0][k]==-1:
            work[k][0]=[-z for z in work[k][0]]; work[k][1]=[-z for z in work[k][1]]
        for u in range(len(work)):
            if u!=k and work[u][0][k]:
                z=work[u][0][k]
                work[u][0]=[a-z*b for a,b in zip(work[u][0],work[k][0])]
                work[u][1]=[a-z*b for a,b in zip(work[u][1],work[k][1])]
        piv.append(C[k])
    # First len(C) rows are transformed selected rows; their original labels come
    # from coefficient vectors. Verify each is a single original row after selection
    # not required. More useful: retain a distinct original selected row basis by
    # taking their nonzero support labels; exact identities are retained below.
    transformed=[]
    for k in range(len(C)):
        comb=work[k][1]
        full=defaultdict(int)
        for z,row in zip(comb,R):
            if z:
                for c,a in row[2].items(): full[c]+=z*a
        assert full[piv[k]]==1 and all(full[c]==0 for c in C if c!=piv[k])
        transformed.append((piv[k],{freecol:full[freecol] for freecol in free_idx if full[freecol]} ,
                            [(R[t][1],z) for t,z in enumerate(comb) if z]))
    return C,R,piv,transformed

blocks={}
for d in sorted({size(p) for p in J}):
    blocks[d]=select_block(d)

# Assemble reductions: chosen transformed graph relations have pivot coordinate 1.
graph={}
for d,(_,_,_,trans) in blocks.items():
    for c,freepart,comb in trans: graph[c]=freepart

def reduce_row(row):
    # subtract v_c*(e_c+graph[c]) for every nonfree coordinate c
    rem=defaultdict(int,row[2])
    coeff={}
    for c in list(graph):
        z=rem.get(c,0)
        if z:
            coeff[c]=z; rem[c]-=z
            for f,a in graph[c].items(): rem[f]-=z*a
    rem={c:z for c,z in rem.items() if z}
    return coeff,rem

# Every row should have zero remainder; this is exact containment in selected lattice.
Pbad=[]; Lbad=[]
Pcoeff=[]; Lcoeff=[]
for row in pieri_rows:
    co,re=reduce_row(row); Pcoeff.append((row[1],[(fmt(J[c]),z) for c,z in co.items()]));
    if re:Pbad.append((row[1],re))
for row in lr_rows:
    co,re=reduce_row(row); Lcoeff.append((row[1],[(fmt(J[c]),z) for c,z in co.items()]));
    if re:Lbad.append((row[1],re))
assert not Pbad and not Lbad

# Exact determinant is ±1 because the recorded Gauss-Jordan pivots are all +1,
# with only row additions/sign changes and column swaps.
rank=len(J)-len(free)
# For auditability, print every transformed graph relation and every exact reduction
# coefficient vector, not merely a digest.
out={
 'parameters':{'r':r,'q':q,'i':i,'j':j,'a':min(q-i,r-j),'b':min(i,j),'N':3,'box':'6^3'},
 'basis':{'F_rank':len(J),'J_columns':[fmt(x) for x in J],'free_F1':[fmt(x) for x in free], 'alternative_F2':['22','221','222']},
 'counts':{'Pieri_rows':len(pieri_rows),'LR_rows':len(lr_rows),'relation_rank':rank,'quotient_rank':3},
 'unimodular_blocks':[],
 'graph_relations':[],
 'containment':{'Pieri_nonzero_remainders':Pbad,'LR_nonzero_remainders':Lbad},
 'exact_reductions':{'Pieri':Pcoeff,'LR':Lcoeff},
 'smith_invariants': ['1']*rank+['0']*3
}
for d,(C,R,piv,trans) in blocks.items():
    out['unimodular_blocks'].append({'degree':d,'rows_available':len(R),'pivot_columns':[fmt(J[c]) for c in piv],
      'determinant':1,'unit_pivots':len(piv)})
    for c,freepart,comb in trans:
        out['graph_relations'].append({'pivot':fmt(J[c]),'relation':'e_%s + %s = 0'%(fmt(J[c]), ' + '.join(('%+d e_%s'%(a,fmt(J[f])) for f,a in freepart.items()) if freepart else '0'),
          'exact_Pieri_row_combination':comb})
# Serialized artifact contains full exact coefficient reductions; terminal output summarizes it.
text=json.dumps(out,sort_keys=True,separators=(',',':'))
print('CASE',out['parameters'])
print('F_RANK',len(J),'PIERI_ROWS',len(pieri_rows),'LR_ROWS',len(lr_rows),'RANK',rank,'Q_RANK',3)
print('FREE',','.join(fmt(x) for x in free))
for b in out['unimodular_blocks']: print('BLOCK',b)
print('GRAPH_RELATIONS')
for x in out['graph_relations']: print(x)
print('CONTAINMENT Pieri_bad=%d LR_bad=%d'%(len(Pbad),len(Lbad)))
print('SMITH diag(1^%d,0^3)'%rank)
print('FULL_CERTIFICATE_SHA256',hashlib.sha256(text.encode()).hexdigest())
print('FULL_CERTIFICATE_JSON_BEGIN')
print(text)
print('FULL_CERTIFICATE_JSON_END')
